      ctx.fillStyle = t.color || line.lineColor;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      lines.forEach((l, i) => ctx.fillText(l, mx, top2 + lh / 2 + i * lh));
      ctx.textAlign = "left";
      ctx.textBaseline = "alphabetic";
