      ctx.globalAlpha = 0.9 * ctx.globalAlpha;
      roundRect(ctx, bx, by - 8, boxW, 16, 3);
      ctx.fillStyle = BADGE_FILL;
      ctx.fill();
      ctx.restore();
      ctx.fillStyle = theme.textColor;
      ctx.textAlign = "left";
      ctx.textBaseline = "middle";
