      ctx.fillStyle = hi.line.color;
      ctx.beginPath();
      ctx.moveTo(T.x0, hi.y0);
      ctx.lineTo(T.xEnd, yAt(hi.y0, hi.y1, T.xEnd));
      ctx.lineTo(T.xEnd, yAt(lo.y0, lo.y1, T.xEnd));
